TYPO03_agentic_grep_04ff0a7f.final_sparql:
PREFIX oriont: <https://orienting.eu/oriont#>
PREFIX oriont-ext: <https://orienting.eu/oriont-ext#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?activity ?activityLabel ?flow ?flowName ?flowType
WHERE {
  {
    ?activity a oriont:Activity ;
              rdfs:label ?activityLabel .
    ?flow oriont:isInputOf ?activity ;
          oriont-ext:hasFlowName ?flowName .
    BIND("input" AS ?flowType)
  }
  UNION
  {
    ?activity a oriont:Activity ;
              rdfs:label ?activityLabel .
    ?flow oriont:isOutputOf ?activity ;
          oriont-ext:hasFlowName ?flowName .
    BIND("output" AS ?flowType)
  }
}

